import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('las-heridas-de-jesus', 'C',
 [dict(t=1698, e=1745, titulo='El Señor no vino a pasear', txt='Él tuvo siete heridas que, por nosotros, sin necesidad, sufrió. La sufrió. No vaya a creer que el Señor Jesucristo vino a pasear en la tierra, ¿no? Tres años y medio, pero por algo: para marcar la diferencia, y que usted y yo pudiéramos. […] Entonces yo le puse «Las heridas de Jesús». Miremos, empecemos, porque si no, el tiempo nos apremia. La primera que encontré es las gotas de sudor que cayeron a la tierra como sangre. Mire qué tremendo. El Señor estaba en angustia.'),
  dict(t=3728, e=3784, titulo='Yo lo que quiero es que Dios me cambie', txt='Dios quiere que resplandezca. ¿Dónde está aquel hombre, aquella mujer que subía a cantar y la miraba? Toda apagada, o todo apagado. No, hermano, ya no hay tiempo. «Ah, hermano, es que perdí la habilidad». Pues practique y regrese con más fuerza, porque todo lo que hacías te lo van a tomar en cuenta. […] Yo lo que quiero es que Dios me hable. Yo lo que quiero es que Dios me cambie.'),
  dict(t=5262, e=5304, titulo='Vino nuevo en odres nuevos', txt='Hoy el Señor ha cambiado tus maldiciones en bendiciones para los que le crean. ¿Cómo nos vamos a dar cuenta? Porque tú y yo vamos a cambiar. Levante la copa, la copa de salvación, la sangre del Señor Jesucristo que nos da gozo. Hoy toda tristeza, todo enojo, toda amargura se va, se va, porque hoy te están dando vino nuevo en odres nuevos. Odres nuevos. Tenías odres rotos, feos, viejos. Hoy el Señor te está dando un odre nuevo.')],
 [dict(t=3312, txt='Usted no puede cambiar a la otra persona, ni la otra persona lo puede cambiar a usted, pero Dios sí puede.'),
  dict(t=3569, txt='Las cosas no son como tú quieres, las cosas son como Dios quiere. Y ese «Dios quiere» es muy diferente a como tú piensas.')],
 ['Jesús pasó por la angustia de Getsemaní por nosotros. ¿Qué tienes hoy en oración que necesitas poner en sus manos?',
  '«Las cosas no son como tú quieres, son como Dios quiere». ¿En qué situación necesitas soltar tu manera de verla?',
  '¿Hay alguna doble vida, o algo a medias, que el Señor te está pidiendo cambiar de forma drástica?'],
 inicio=1388)
